21:     for (x, y) in a.parts.iter().zip(b.parts.iter()) {
22:         let ord = x.cmp(y);
23:         if ord != std::cmp::Ordering::Equal {
24:             return ord;
25:         }
26:     }
27:     a.parts.len().cmp(&b.parts.len())
28: }

